import java.util.*;class Solution{List<String>o=new ArrayList<>();char[][]p={{'0','0'},{'1','1'},{'6','9'},{'8','8'},{'9','6'}};void f(char[]s,int l,int r){if(l>r){o.add(new String(s));return;}for(char[]x:p){if(l==0&&r>0&&x[0]=='0')continue;if(l==r&&x[0]!=x[1])continue;s[l]=x[0];s[r]=x[1];f(s,l+1,r-1);}}public List<String> findStrobogrammatic(int n){f(new char[n],0,n-1);return o;}}
